import java.util.ArrayList;
import java.util.Comparator;
class Person { String name; int age; Person(String n,int a){name=n;age=a;} public String toString(){return name+":"+age;} }
public class Main { public static void main(String[] args) { ArrayList<Person> p = new ArrayList<>(); p.add(new Person("Ravi",30)); p.add(new Person("Asha",24)); p.sort(Comparator.comparingInt(x -> x.age)); System.out.println(p); } }

import java.util.ArrayList;
import java.util.Comparator;
class Item { String name; int price; Item(String n,int p){name=n;price=p;} public String toString(){return name;} }
public class Main { public static void main(String[] args) { ArrayList<Item> a = new ArrayList<>(); a.add(new Item("Zed",10)); a.add(new Item("Ari",10)); a.add(new Item("Bee",8)); a.sort(Comparator.comparingInt((Item x)->x.price).thenComparing(x->x.name)); System.out.println(a); } }

import java.util.ArrayList;
import java.util.Comparator;
public class Main { public static void main(String[] args) { ArrayList<Integer> a = new ArrayList<>(); a.add(2); a.add(9); a.add(4); a.sort(Comparator.<Integer>naturalOrder().reversed()); System.out.println(a); } }

import java.util.ArrayList;
import java.util.Comparator;
public class Main { public static void main(String[] args) { ArrayList<String> a = new ArrayList<>(); a.add("pear"); a.add(null); a.add("apple"); a.sort(Comparator.nullsLast(Comparator.naturalOrder())); System.out.println(a); } }

